   if($Which -eq 'routed-test' -and $x.expert_order_checked){throw 'Control unexpectedly reordered'}
  }elseif($x.kind -eq 'prepared_moe_norm_scan'){
   if($x.norm_bit_differences -ne 0 -or -not $x.validate_only -or $x.scaled_fallback){throw 'Original norm mismatch'}
  }else{throw 'Unexpected numerical report'}
 }
 if(@($reports|Where-Object {$_.kind -eq 'prepared_moe_norm_scan'}).Count -ne 2 -or @($reports|Where-Object {$_.kind -eq 'routed_compaction_comparison'}).Count -ne 4){throw 'Missing numerical family'}
 if($Which -eq 'expert-test' -and @($reports|Where-Object {$_.kind -eq 'moe_expert_order_permutation'}).Count -ne 72){throw 'Missing permutation cases'}
}
